/*
 * conv1d.c — software Conv1D engine; the block that replaces the NPU.
 * Bare-metal RV32IM. No stdlib. No malloc. No float. No MMIO.
 *
 * See conv1d.h for why this is bit-identical to the NPU launch it
 * replaces, and for the cost argument.
 */

#include <stdint.h>
#include "conv1d.h"
#include "model_layout.h"
#include "features.h"

/* Weight tiles and biases (src/model_weights_data.c), generated by
 * tools/extract_npu_weights.py. Layout: tile[row * TILE_LANES + filter]. */
extern const unsigned char g_conv_weight_l1[TILE_BYTES];
extern const unsigned char g_conv_weight_l2_g0[TILE_BYTES];
extern const unsigned char g_conv_weight_l2_g1[TILE_BYTES];
extern const int32_t g_conv_bias_l1[L1_FILTERS];
extern const int32_t g_conv_bias_l2[L2_FILTERS];

/* round_shift_i32() / clamp_i8_sym() -- see features.c for the canonical
 * (also-static) copies; duplicated here rather than exported across
 * translation units, matching this codebase's existing per-file-static
 * convention for these small integer-quantization primitives. Must stay
 * identical to npu_model.round_shift() / npu_model.clamp_i8_sym(). */
static int32_t round_shift_i32(int32_t v, int32_t shift)
{
    int32_t half, mag;

    if (shift <= 0) {
        return v;
    }
    half = (int32_t)1 << (shift - 1);
    if (v >= 0) {
        return (v + half) >> shift;
    }
    mag = ((-v) + half) >> shift;
    return -mag;
}

static int8_t clamp_i8_sym(int32_t v)
{
    if (v > 127) {
        return 127;
    }
    if (v < -127) {
        return -127;
    }
    return (int8_t)v;
}

void conv1d_tile(const uint8_t *weight_tile,
                 const uint8_t *act_tile,
                 int32_t acc_out[CONV1D_TILE_ACCS])
{
    uint32_t r, f, j;

    for (j = 0U; j < CONV1D_TILE_ACCS; j++) {
        acc_out[j] = 0;
    }

    for (r = 0U; r < TILE_ROWS; r++) {
        const uint8_t *w_row = &weight_tile[r * TILE_LANES];
        const uint8_t *a_row = &act_tile[r * TILE_LANES];
        int32_t w[TILE_LANES];
        int32_t a[TILE_LANES];
        uint32_t nonzero = 0U;

        /*
         * Widen both rows once, and note whether either is all-zero.
         * Rows at or past the layer's im2col depth (20 of 32 for layer 1,
         * 24 of 32 for layer 2) are structural zero padding in the weight
         * tiles, so this skip removes a third of the nominal MAC count
         * without changing a single accumulator: adding 0 * a is a no-op,
         * not a rounding shortcut. The NPU had to clock those rows
         * through its MAC array regardless.
         */
        for (f = 0U; f < TILE_LANES; f++) {
            w[f] = (int32_t)(int8_t)w_row[f];
            a[f] = (int32_t)(int8_t)a_row[f];
            nonzero |= (uint32_t)w[f] | (uint32_t)a[f];
        }
        if (nonzero == 0U) {
            continue;
        }

        for (f = 0U; f < TILE_LANES; f++) {
            if (w[f] == 0) {
                continue;
            }
            for (j = 0U; j < TILE_LANES; j++) {
                acc_out[f * TILE_LANES + j] += w[f] * a[j];
            }
        }
    }
}

void conv1d_layer1(const int8_t tensor[SENSOR_WINDOW_LEN][N_CHANNELS_IN],
                   int8_t out[SENSOR_WINDOW_LEN][L1_FILTERS])
{
    static uint8_t s_act[TILE_BYTES];
    static int32_t s_acc[CONV1D_TILE_ACCS];
    uint32_t group, f, j;

    for (group = 0U; group < L1_TILES; group++) {
        build_l1_activation_image(tensor, group, s_act);
        conv1d_tile(g_conv_weight_l1, s_act, s_acc);

        for (f = 0U; f < L1_FILTERS; f++) {
            for (j = 0U; j < TILE_LANES; j++) {
                int32_t raw  = s_acc[f * TILE_LANES + j] + g_conv_bias_l1[f];
                int32_t relu = (raw > 0) ? raw : 0;
                uint32_t t   = group * TILE_LANES + j;
                out[t][f] = clamp_i8_sym(round_shift_i32(relu, L1_REQUANT_SHIFT));
            }
        }
    }
}

void conv1d_layer2(const int8_t pooled[POOL_LEN][L2_IN_CHANNELS],
                   int8_t out[POOL_LEN][L2_FILTERS])
{
    static uint8_t s_act[TILE_BYTES];
    static int32_t s_acc[CONV1D_TILE_ACCS];
    uint32_t fg, g, fi, j;

    /*
     * Filter group outer, timestep group inner -- the order the NPU build
     * used, chosen there because the weight tile was SRAM-resident and
     * reloading it cost 256 CPU byte-stores. Nothing forces that order any
     * more (there is no resident weight state to amortise), but it is kept
     * so the tile sequence, and therefore the per-tile golden vectors,
     * match the NPU build one for one.
     */
    for (fg = 0U; fg < L2_FILTER_GROUPS; fg++) {
        const unsigned char *weight_tile =
            (fg == 0U) ? g_conv_weight_l2_g0 : g_conv_weight_l2_g1;

        for (g = 0U; g < L2_TIMESTEP_GROUPS; g++) {
            build_l2_activation_image(pooled, g, s_act);
            conv1d_tile(weight_tile, s_act, s_acc);

            for (fi = 0U; fi < TILE_LANES; fi++) {
                uint32_t f = fg * TILE_LANES + fi;
                for (j = 0U; j < TILE_LANES; j++) {
                    int32_t raw  = s_acc[fi * TILE_LANES + j] + g_conv_bias_l2[f];
                    int32_t relu = (raw > 0) ? raw : 0;
                    uint32_t t   = g * TILE_LANES + j;
                    out[t][f] = clamp_i8_sym(round_shift_i32(relu, L2_REQUANT_SHIFT));
                }
            }
        }
    }
}
